@Component("chargeback-handler")
@ProcessingGroup("chargeback-processing-group")
public class ChargebackEventHandler {
	
	// core constructor
	ChargebackEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateChargebackEvent
     */
    @EventHandler
    public void handle( CreateChargebackEvent event) {
        entityManager.persist(new Chargeback(event.getChargebackId(), event.getChargebackReference(), event.getAmount(), event.getPostedAt(), event.getDispute(), event.getTransaction(), event.getStage(), event.getStatus()));
    }

    /*
     * @param	event UpdateChargebackEvent
     */
    @EventHandler
    public Chargeback handle( UpdateChargebackEvent event) {
    	entityManager.merge(new Chargeback(event.getChargebackId(), event.getChargebackReference(), event.getAmount(), event.getPostedAt(), event.getDispute(), event.getTransaction(), event.getStage(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteChargebackEvent
     */
    @EventHandler
    public void on( DeleteChargebackEvent event) {
    	Chargeback entity = new Chargeback();
   
    	// ------------------------------------------
    	// apply the ChargebackId
    	// ------------------------------------------
    	entity.setChargebackId( event.getChargebackId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ChargebackRepository chargebackEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ChargebackEventHandler.class.getName());

}
